package cronlite

import (
	"errors"
	"sort"
	"strings"
)

var errBad = errors.New("cronlite: bad input")

var ranges = [3][2]int64{{0, 59}, {0, 23}, {1, 30}}

func val(s string, lo, hi int64) (int64, error) {
	if len(s) < 1 || len(s) > 2 {
		return 0, errBad
	}
	var v int64
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, errBad
		}
		v = v*10 + int64(s[i]-'0')
	}
	if v < lo || v > hi {
		return 0, errBad
	}
	return v, nil
}

func field(text string, lo, hi int64) ([]int64, error) {
	set := map[int64]bool{}
	for _, item := range strings.Split(text, ",") {
		if item == "" {
			return nil, errBad
		}
		base, stepText, slash := strings.Cut(item, "/")
		step := int64(1)
		if slash {
			s, err := val(stepText, 0, 99)
			if err != nil || s < 1 {
				return nil, errBad
			}
			step = s
		}
		var a, b int64
		switch {
		case base == "*":
			a, b = lo, hi
		case strings.Contains(base, "-"):
			x, y, _ := strings.Cut(base, "-")
			var err error
			if a, err = val(x, lo, hi); err != nil {
				return nil, err
			}
			if b, err = val(y, lo, hi); err != nil {
				return nil, err
			}
			if a > b {
				return nil, errBad
			}
		default:
			var err error
			if a, err = val(base, lo, hi); err != nil {
				return nil, err
			}
			b = a
			if slash {
				b = hi
			}
		}
		for v := a; v <= b; v += step {
			set[v] = true
		}
	}
	out := make([]int64, 0, len(set))
	for v := range set {
		out = append(out, v)
	}
	sort.Slice(out, func(i, j int) bool { return out[i] < out[j] })
	return out, nil
}

func Expand(spec string) ([][]int64, error) {
	parts := strings.Split(spec, " ")
	if len(parts) != 3 {
		return nil, errBad
	}
	out := make([][]int64, 3)
	for i, p := range parts {
		f, err := field(p, ranges[i][0], ranges[i][1])
		if err != nil {
			return nil, err
		}
		out[i] = f
	}
	return out, nil
}

func sets(spec string) ([3]map[int64]bool, error) {
	var out [3]map[int64]bool
	lists, err := Expand(spec)
	if err != nil {
		return out, err
	}
	for i, l := range lists {
		out[i] = map[int64]bool{}
		for _, v := range l {
			out[i][v] = true
		}
	}
	return out, nil
}

func match(s [3]map[int64]bool, t int64) bool {
	return s[0][t%60] && s[1][(t/60)%24] && s[2][(t/1440)%30+1]
}

func Matches(spec string, t int64) (bool, error) {
	s, err := sets(spec)
	if err != nil {
		return false, err
	}
	if t < 0 {
		return false, errBad
	}
	return match(s, t), nil
}

func NextAfter(spec string, t int64) (int64, error) {
	s, err := sets(spec)
	if err != nil {
		return 0, err
	}
	if t < 0 {
		return 0, errBad
	}
	x := t + 1
	for !match(s, x) {
		x++
	}
	return x, nil
}

func CountBetween(spec string, start, end int64) (int64, error) {
	s, err := sets(spec)
	if err != nil {
		return 0, err
	}
	if start < 0 || end < start {
		return 0, errBad
	}
	var n int64
	for x := start; x < end; x++ {
		if match(s, x) {
			n++
		}
	}
	return n, nil
}

