	if err != nil {
		return fmt.Sprint(v)
	}
	return string(b)
}

func vxCall(fn string, a []any) (got any, failed bool, known bool) {
	switch fn {
	case "expand":
		r, err := Expand(vxStr(a[0]))
		if err != nil {
			return nil, true, true
		}
		return vxJ(r), false, true
	case "matches":
		r, err := Matches(vxStr(a[0]), vxInt(a[1]))
		if err != nil {
			return nil, true, true
		}
		return vxJ(r), false, true
	case "next_after":
		r, err := NextAfter(vxStr(a[0]), vxInt(a[1]))
		if err != nil {
			return nil, true, true
		}
		return vxJ(r), false, true
	case "count_between":
		r, err := CountBetween(vxStr(a[0]), vxInt(a[1]), vxInt(a[2]))
		if err != nil {
			return nil, true, true
		}
		return vxJ(r), false, true
	}
	return nil, false, false
}

